【主要应用】区间修改 + 区间查询、区间最值、区间历史最值、扫描线、动态开点、线段树合并、李超线段树。
【应用方式】懒标记下传；扫描线求矩形面积并/周长；动态开点节省空间；线段树合并处理树上问题；李超线段树维护一次函数最值。
【模板代码】
```cpp
// 区间加 + 区间求和
void pushup(int p) { sum[p] = sum[p<<1] + sum[p<<1|1]; }
void pushdown(int p, int l, int r) {
    if (!add[p]) return;
    int mid = (l + r) >> 1;
    sum[p<<1] += add[p] * (mid - l + 1); add[p<<1] += add[p];
    sum[p<<1|1] += add[p] * (r - mid); add[p<<1|1] += add[p];
    add[p] = 0;
}
void update(int p, int l, int r, int ql, int qr, int v) {
    if (ql <= l && r <= qr) { sum[p] += v * (r - l + 1); add[p] += v; return; }
    pushdown(p, l, r);
    int mid = (l + r) >> 1;
    if (ql <= mid) update(p<<1, l, mid, ql, qr, v);
    if (qr > mid) update(p<<1|1, mid+1, r, ql, qr, v);
    pushup(p);
}
```

