【模板代码】
```cpp
// 可持久化数组
int update(int pre, int l, int r, int pos, int val) {
    int p = ++tot;
    if (l == r) { val[p] = val; return p; }
    int mid = (l + r) >> 1;
    if (pos <= mid) lc[p] = update(lc[pre], l, mid, pos, val), rc[p] = rc[pre];
    else rc[p] = update(rc[pre], mid+1, r, pos, val), lc[p] = lc[pre];
    return p;
}
```

