【主要应用】树上路径修改与查询、子树修改与查询、LCA、树上第 k 大。
【应用方式】重链剖分：两次 DFS 求 size、重儿子、top、dfn；用线段树维护 dfn 序上的区间信息；路径查询不断跳 top。
【模板代码】
```cpp
// 树链剖分两次 DFS
void dfs1(int u, int fa) {
    sz[u] = 1; dep[u] = dep[fa] + 1; fa[u] = fa;
    for (int v : g[u]) if (v != fa) {
        dfs1(v, u);
        sz[u] += sz[v];
        if (sz[v] > sz[son[u]]) son[u] = v;
    }
}
void dfs2(int u, int topf) {
    dfn[u] = ++cnt; top[u] = topf;
    if (son[u]) dfs2(son[u], topf);
    for (int v : g[u]) if (v != fa[u] && v != son[u]) dfs2(v, v);
}
// 路径查询
int query_path(int u, int v) {
    int res = 0;
    while (top[u] != top[v]) {
        if (dep[top[u]] < dep[top[v]]) swap(u, v);
        res += query(1, 1, n, dfn[top[u]], dfn[u]);
        u = fa[top[u]];
    }
    if (dep[u] > dep[v]) swap(u, v);
    res += query(1, 1, n, dfn[u], dfn[v]);
    return res;
}
```

