// Treap 旋转
void rotate(Node *&p, int d) {
    Node *q = p->ch[d ^ 1];
    p->ch[d ^ 1] = q->ch[d];
    q->ch[d] = p;
    p = q;
}
void insert(Node *&p, int x) {
    if (!p) { p = new Node(x); return; }
    int d = x > p->val;
    insert(p->ch[d], x);
    if (p->ch[d]->pri < p->pri) rotate(p, d ^ 1);
}
