// Treap 删除
void erase(Node *&p, int x) {
    if (p->val == x) {
        if (!p->l || !p->r) p = p->l ? p->l : p->r;
        else {
            int d = p->l->pri < p->r->pri;
            rotate(p, d);
            erase(p->ch[d], x);
        }
    } else erase(p->ch[x > p->val], x);
}
