// Splay 旋转
void rotate(int x) {
    int y = fa[x], z = fa[y], k = (ch[y][1] == x);
    if (z) ch[z][ch[z][1] == y] = x;
    fa[x] = z;
    ch[y][k] = ch[x][k ^ 1];
    if (ch[x][k ^ 1]) fa[ch[x][k ^ 1]] = y;
    ch[x][k ^ 1] = y; fa[y] = x;
    pushup(y); pushup(x);
}
void splay(int x, int goal) {
    while (fa[x] != goal) {
        int y = fa[x], z = fa[y];
        if (z != goal) rotate((ch[y][1] == x) ^ (ch[z][1] == y) ? x : y);
        rotate(x);
    }
    if (!goal) root = x;
}
