【主要应用】动态连通性、动态路径查询、动态最小生成树、维护森林。
【应用方式】LCT 用 Splay 维护每一条偏爱路径；支持 access、makeroot、link、cut、findroot；常用于动态图问题。
【模板代码】
```cpp
// LCT 核心操作
void access(int x) {
    for (int y = 0; x; x = fa[y = x]) splay(x), ch[x][1] = y, pushup(x);
}
void makeroot(int x) { access(x); splay(x); rev[x] ^= 1; }
int findroot(int x) {
    access(x); splay(x);
    while (ch[x][0]) pushdown(x), x = ch[x][0];
    splay(x); return x;
}
void split(int x, int y) { makeroot(x); access(y); splay(y); }
void link(int x, int y) { makeroot(x); if (findroot(y) != x) fa[x] = y; }
void cut(int x, int y) {
    makeroot(x);
    if (findroot(y) == x && fa[y] == x && !ch[y][0]) ch[x][1] = fa[y] = 0, pushup(x);
}
```

